-- Executable observations and gates for frozen Stage 1 acceptance v3.
\set ON_ERROR_STOP on
SET TIME ZONE 'UTC';
\pset format unaligned
\pset null 'NULL'
CREATE OR REPLACE FUNCTION stage1_input(c text,rid text,eid text,reporter text,at_time timestamptz,d text) RETURNS TABLE(case_id text,actor_evidence text,request_id text,equipment_id text,reported_by text,reported_at text,description_utf8_hex text) LANGUAGE sql AS $$ SELECT c,'reporter',rid,eid,reporter,to_char(at_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),encode(convert_to(d,'UTF8'),'hex') $$;
-- Rejection encoding is intentionally not asserted; the post-call count gates prove no write.
CREATE OR REPLACE FUNCTION stage1_rejected(c text,rid text,eid text,reporter text,at_time timestamptz,d text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM report_equipment_fault(rid,eid,reporter,at_time,d); RAISE EXCEPTION '% unexpectedly accepted',c; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE '%'||c||' unexpectedly accepted' THEN RAISE; END IF; END $$;
CREATE OR REPLACE FUNCTION stage1_setup(c text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN TRUNCATE maintenance_request; INSERT INTO equipment(equipment_id,status) VALUES ('eq-stage1-known','available'),('eq-stage1-other','available') ON CONFLICT(equipment_id) DO UPDATE SET status=EXCLUDED.status; IF (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION '% setup failed',c; END IF; END $$;

-- Accepted-row observation and exact all-field/count assertion.
CREATE OR REPLACE FUNCTION stage1_accepted(c text,rid text,at_time timestamptz,d text,expected_total bigint) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id=rid AND equipment_id='eq-stage1-known' AND reported_by='reporter-stage1' AND reported_at=at_time AND description=d AND status='open' AND scheduled_for IS NULL AND completed_at IS NULL)<>1 OR (SELECT count(*) FROM maintenance_request)<>expected_total THEN RAISE EXCEPTION '% failed',c; END IF; END $$;

-- S1-01
SELECT stage1_setup('S1-01'); SELECT * FROM stage1_input('S1-01','req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30:00Z','Hydraulic pressure warning observed'); SELECT 'S1-01 setup' observation,count(*) request_count FROM maintenance_request; SELECT report_equipment_fault('req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30:00Z','Hydraulic pressure warning observed') accepted_request_id; SELECT 'S1-01 accepted' call_outcome; SELECT 'S1-01 row' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage1-01'; SELECT 'S1-01 total' observation,count(*) request_count FROM maintenance_request; SELECT stage1_accepted('S1-01','req-stage1-01','2030-01-15T10:30:00Z','Hydraulic pressure warning observed',1);

-- S1-02
SELECT stage1_setup('S1-02'); SELECT * FROM stage1_input('S1-02','req-stage1-02','eq-stage1-unknown','reporter-stage1','2030-01-15T10:31:00Z','Unknown asset probe'); SELECT 'S1-02 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_rejected('S1-02','req-stage1-02','eq-stage1-unknown','reporter-stage1','2030-01-15T10:31:00Z','Unknown asset probe'); SELECT 'S1-02 rejected' call_outcome; SELECT 'S1-02 unknown_equipment' observation,count(*) unknown_equipment_request_count FROM maintenance_request WHERE equipment_id='eq-stage1-unknown'; SELECT 'S1-02 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-02'; SELECT 'S1-02 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE equipment_id='eq-stage1-unknown')<>0 OR (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-02')<>0 OR (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-02 failed'; END IF; END $$;

-- S1-03 / S1-05..S1-09; each is reset and independently asserted.
SELECT stage1_setup('S1-03'); SELECT * FROM stage1_input('S1-03','req-stage1-03','eq-stage1-known','reporter-stage1','2030-01-15T10:32:00Z',''); SELECT 'S1-03 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_rejected('S1-03','req-stage1-03','eq-stage1-known','reporter-stage1','2030-01-15T10:32:00Z',''); SELECT 'S1-03 rejected' call_outcome; SELECT 'S1-03 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-03'; SELECT 'S1-03 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-03')<>0 OR (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-03 failed'; END IF; END $$;
SELECT stage1_setup('S1-05'); SELECT * FROM stage1_input('S1-05','req-stage1-05','eq-stage1-known','reporter-stage1','2030-01-15T10:35:00Z','   '); SELECT 'S1-05 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_rejected('S1-05','req-stage1-05','eq-stage1-known','reporter-stage1','2030-01-15T10:35:00Z','   '); SELECT 'S1-05 rejected' call_outcome; SELECT 'S1-05 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-05'; SELECT 'S1-05 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-05')<>0 OR (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-05 failed'; END IF; END $$;
SELECT stage1_setup('S1-06'); SELECT * FROM stage1_input('S1-06','req-stage1-06','eq-stage1-known','reporter-stage1','2030-01-15T10:36:00Z',E'\t'); SELECT 'S1-06 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_rejected('S1-06','req-stage1-06','eq-stage1-known','reporter-stage1','2030-01-15T10:36:00Z',E'\t'); SELECT 'S1-06 rejected' call_outcome; SELECT 'S1-06 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-06'; SELECT 'S1-06 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-06')<>0 OR (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-06 failed'; END IF; END $$;
SELECT stage1_setup('S1-07'); SELECT * FROM stage1_input('S1-07','req-stage1-07','eq-stage1-known','reporter-stage1','2030-01-15T10:37:00Z',E'\n'); SELECT 'S1-07 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_rejected('S1-07','req-stage1-07','eq-stage1-known','reporter-stage1','2030-01-15T10:37:00Z',E'\n'); SELECT 'S1-07 rejected' call_outcome; SELECT 'S1-07 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-07'; SELECT 'S1-07 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-07')<>0 OR (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-07 failed'; END IF; END $$;
SELECT stage1_setup('S1-08'); SELECT * FROM stage1_input('S1-08','req-stage1-08','eq-stage1-known','reporter-stage1','2030-01-15T10:38:00Z','　'); SELECT 'S1-08 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_rejected('S1-08','req-stage1-08','eq-stage1-known','reporter-stage1','2030-01-15T10:38:00Z','　'); SELECT 'S1-08 rejected' call_outcome; SELECT 'S1-08 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-08'; SELECT 'S1-08 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-08')<>0 OR (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-08 failed'; END IF; END $$;
SELECT stage1_setup('S1-09'); SELECT * FROM stage1_input('S1-09','req-stage1-09','eq-stage1-known','reporter-stage1','2030-01-15T10:39:00Z',E' \t\n　'); SELECT 'S1-09 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_rejected('S1-09','req-stage1-09','eq-stage1-known','reporter-stage1','2030-01-15T10:39:00Z',E' \t\n　'); SELECT 'S1-09 rejected' call_outcome; SELECT 'S1-09 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-09'; SELECT 'S1-09 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-09')<>0 OR (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-09 failed'; END IF; END $$;

-- S1-04 retains its first accepted call within the same fixture.
SELECT stage1_setup('S1-04'); SELECT 'S1-04 setup' observation,count(*) request_count FROM maintenance_request; SELECT * FROM stage1_input('S1-04 first','req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30:00Z','Hydraulic pressure warning observed'); SELECT report_equipment_fault('req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30:00Z','Hydraulic pressure warning observed') first_accepted_request_id; SELECT 'S1-04 first accepted' call_outcome; SELECT * FROM stage1_input('S1-04','req-stage1-04','eq-stage1-known','reporter-stage1','2030-01-15T10:33:00Z','Hydraulic pressure warning observed'); SELECT report_equipment_fault('req-stage1-04','eq-stage1-known','reporter-stage1','2030-01-15T10:33:00Z','Hydraulic pressure warning observed') accepted_request_id; SELECT 'S1-04 accepted' call_outcome; SELECT 'S1-04 rows' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id IN ('req-stage1-01','req-stage1-04') ORDER BY request_id; SELECT 'S1-04 total' observation,count(*) request_count FROM maintenance_request; SELECT stage1_accepted('S1-04 first','req-stage1-01','2030-01-15T10:30:00Z','Hydraulic pressure warning observed',2); SELECT stage1_accepted('S1-04','req-stage1-04','2030-01-15T10:33:00Z','Hydraulic pressure warning observed',2);

-- S1-10 / S1-11
SELECT stage1_setup('S1-10'); SELECT * FROM stage1_input('S1-10','req-stage1-10','eq-stage1-known','reporter-stage1','2030-01-15T10:40:00Z','Bearing temperature above normal'); SELECT 'S1-10 setup' observation,count(*) request_count FROM maintenance_request; SELECT report_equipment_fault('req-stage1-10','eq-stage1-known','reporter-stage1','2030-01-15T10:40:00Z','Bearing temperature above normal') accepted_request_id; SELECT 'S1-10 accepted' call_outcome; SELECT 'S1-10 row' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage1-10'; SELECT 'S1-10 total' observation,count(*) request_count FROM maintenance_request; SELECT stage1_accepted('S1-10','req-stage1-10','2030-01-15T10:40:00Z','Bearing temperature above normal',1);
SELECT stage1_setup('S1-11'); SELECT * FROM stage1_input('S1-11','req-stage1-11','eq-stage1-known','reporter-stage1','2030-01-15T10:41:00Z','  Bearing temperature above normal  '); SELECT 'S1-11 setup' observation,count(*) request_count FROM maintenance_request; SELECT report_equipment_fault('req-stage1-11','eq-stage1-known','reporter-stage1','2030-01-15T10:41:00Z','  Bearing temperature above normal  ') accepted_request_id; SELECT 'S1-11 accepted' call_outcome; SELECT 'S1-11 row' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage1-11'; SELECT 'S1-11 total' observation,count(*) request_count FROM maintenance_request; SELECT stage1_accepted('S1-11','req-stage1-11','2030-01-15T10:41:00Z','  Bearing temperature above normal  ',1);
SELECT 'STAGE1_ACCEPTANCE_V3_PASS' result,current_database() database_name,current_schema() schema_name;
